package com.bankpli.javabank.audit;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/audit")public class AuditController{private final AuditService service;public AuditController(AuditService s){service=s;}@GetMapping public List<AuditRecord> list(){return service.list();}@PostMapping("/parse")public AuditService.ParsedTransaction parse(@RequestBody Map<String,String>b){return service.parse(b.get("line"));}@GetMapping("/report")public Map<String,Object> report(){List<AuditRecord> rows=service.list();return Map.of("generatedAt",java.time.Instant.now(),"recordCount",rows.size(),"records",rows);}}
